Source code in <code>pygent/models.py</code> <pre><code>def chat(self, messages: List[Dict[str, Any]], model: str, tools: Any) -&gt; Message:
    try:
        serialized = [
            asdict(m) if is_dataclass(m) else m
            for m in messages
        ]
        kwargs = {"model": model, "messages": serialized}
        if tools:
            kwargs.update(tools=tools, tool_choice="auto")
        client = self.client if self.client is not None else openai
        resp = client.chat.completions.create(**kwargs)
        return resp.choices[0].message
    except Exception as exc:
        raise APIError(str(exc)) from exc
